import { forwardRef } from 'react';

interface AvatarProps extends React.HTMLAttributes<HTMLDivElement> {
  src?: string;
  alt?: string;
  name?: string;
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  status?: 'online' | 'offline' | 'busy' | 'away';
  shape?: 'circle' | 'square';
}

export const Avatar = forwardRef<HTMLDivElement, AvatarProps>(
  ({ className = '', src, alt, name, size = 'md', status, shape = 'circle', ...props }, ref) => {
    const sizes = {
      xs: 'w-6 h-6 text-xs',
      sm: 'w-8 h-8 text-sm',
      md: 'w-10 h-10 text-base',
      lg: 'w-12 h-12 text-lg',
      xl: 'w-16 h-16 text-xl',
    };
    const statusSizes = {
      xs: 'w-1.5 h-1.5',
      sm: 'w-2 h-2',
      md: 'w-2.5 h-2.5',
      lg: 'w-3 h-3',
      xl: 'w-4 h-4',
    };
    const statusColors = {
      online: 'bg-emerald-400',
      offline: 'bg-gray-500',
      busy: 'bg-rose-400',
      away: 'bg-amber-400',
    };

    const getInitials = (name: string) =>
      name
        .split(' ')
        .map(n => n[0])
        .join('')
        .toUpperCase()
        .slice(0, 2);

    const hasImage = src && src.trim() !== '';
    const initials = name ? getInitials(name) : '?';
    const bgColor = name ? `bg-[hsl(${name.split('').reduce((a, c) => a + c.charCodeAt(0), 0) % 360},70%,50%)]` : 'bg-gray-600';

    return (
      <div
        ref={ref}
        className={`relative inline-flex shrink-0 ${sizes[size]} ${shape === 'circle' ? 'rounded-full' : 'rounded-xl'} overflow-hidden ${className}`}
        {...props}
      >
        {hasImage ? (
          <img
            src={src}
            alt={alt || name || 'Avatar'}
            className="w-full h-full object-cover"
            onError={e => { e.currentTarget.style.display = 'none'; }}
          />
        ) : (
          <div className={`w-full h-full flex items-center justify-center font-medium text-white ${bgColor}`}>
            {initials}
          </div>
        )}
        {status && (
          <span
            className={`absolute bottom-0 right-0 border-2 border-[#0d1225] rounded-full ${statusSizes[size]} ${statusColors[status]}`}
            aria-label={`Status: ${status}`}
          />
        )}
      </div>
    );
  }
);
Avatar.displayName = 'Avatar';

interface AvatarGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  max?: number;
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
}

export const AvatarGroup = forwardRef<HTMLDivElement, AvatarGroupProps>(
  ({ className = '', children, max = 5, size = 'md', ...props }, ref) => {
    const sizes = {
      xs: '-space-x-1',
      sm: '-space-x-1.5',
      md: '-space-x-2',
      lg: '-space_x-2.5',
      xl: '-space-x-3',
    };
    const kids = React.Children.toArray(children).slice(0, max);
    const remaining = React.Children.count(children) - max;

    return (
      <div ref={ref} className={`flex ${sizes[size]} ${className}`} {...props}>
        {kids.map((child, index) => (
          <div key={index} className="relative z-[auto]">{child}</div>
        ))}
        {remaining > 0 && (
          <div className={`relative flex items-center justify-center border-2 border-[#0d1225] ${sizes[size].replace('-space', '').replace('x', '')} rounded-full bg-white/5 text-gray-400 text-xs font-medium`}>
            +{remaining}
          </div>
        )}
      </div>
    );
  }
);
AvatarGroup.displayName = 'AvatarGroup';
